import { ChevronLeftIcon, ChevronRightIcon } from 'lucide-react'
import * as React from 'react'
import { Button } from '@/components/ui/button'

interface TableFooterProps {
  rowCount: number
  showPagination: boolean
  pageIndex: number
  pageCount: number
  canPreviousPage: boolean
  canNextPage: boolean
  onPreviousPage: () => void
  onNextPage: () => void
  onShiftTabToTable: () => void
}

export const TableFooter = React.forwardRef<HTMLDivElement, TableFooterProps>(
  function TableFooter(
    { rowCount, showPagination, pageIndex, pageCount, canPreviousPage, canNextPage, onPreviousPage, onNextPage, onShiftTabToTable },
    ref
  ) {
    return (
      <div
        ref={ref}
        className="flex items-center justify-between"
        onKeyDown={(e) => {
          if (e.key === 'Tab' && e.shiftKey && rowCount > 0) {
            const focusables = Array.from(
              (ref as React.RefObject<HTMLDivElement>).current?.querySelectorAll<HTMLElement>('button:not([disabled]),[tabindex="0"]') ?? []
            )
            if (focusables[0] === document.activeElement) {
              e.preventDefault()
              e.stopPropagation()
              onShiftTabToTable()
            }
          }
        }}
      >
        <p className="text-xs text-foreground font-semibold text-center w-full">
          {rowCount} row{rowCount !== 1 ? 's' : ''}
        </p>
        {showPagination && (
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground whitespace-nowrap">
              Page {pageIndex + 1} of {Math.max(pageCount, 1)}
            </span>
            <Button
              variant="outline"
              size="icon"
              className="h-7 w-7"
              onClick={onPreviousPage}
              disabled={!canPreviousPage}
            >
              <ChevronLeftIcon className="h-3.5 w-3.5" />
              <span className="sr-only">Previous page</span>
            </Button>
            <Button
              variant="outline"
              size="icon"
              className="h-7 w-7"
              onClick={onNextPage}
              disabled={!canNextPage}
            >
              <ChevronRightIcon className="h-3.5 w-3.5" />
              <span className="sr-only">Next page</span>
            </Button>
          </div>
        )}
      </div>
    )
  }
)

import { CheckIcon, ChevronRightIcon } from 'lucide-react'
import * as React from 'react'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { cn } from '@/lib/utils'
import type { TableActiveFilter, TableFilterDef, TableFilterOption } from './types'

interface FilterMenuProps<TData> {
  filterDefs: TableFilterDef<TData>[]
  activeFilters: TableActiveFilter[]
  onToggleValue: (filterId: string, value: string) => void
  open: boolean
  onOpenChange: (open: boolean) => void
  trigger: React.ReactNode
}

export function FilterMenu<TData>({
  filterDefs,
  activeFilters,
  onToggleValue,
  open,
  onOpenChange,
  trigger,
}: FilterMenuProps<TData>) {
  const [mainSearch, setMainSearch] = React.useState('')
  const [subSearch, setSubSearch] = React.useState('')
  const [highlightedMain, setHighlightedMain] = React.useState(-1)
  const [highlightedSub, setHighlightedSub] = React.useState(-1)
  const [focusedPanel, setFocusedPanel] = React.useState<'main' | 'sub'>('main')
  const [subMenuTop, setSubMenuTop] = React.useState(0)

  const mainInputRef = React.useRef<HTMLInputElement>(null)
  const subInputRef = React.useRef<HTMLInputElement>(null)
  const mainListRef = React.useRef<HTMLDivElement>(null)
  const subListRef = React.useRef<HTMLDivElement>(null)
  const popoverRef = React.useRef<HTMLDivElement>(null)
  const itemRefs = React.useRef<(HTMLButtonElement | null)[]>([])
  const mousePos = React.useRef({ x: 0, y: 0 })
  const anchorPos = React.useRef({ x: 0, y: 0 })  // mouse pos when current item was selected
  const aimTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null)
  const subMenuRef = React.useRef<HTMLDivElement>(null)

  type SearchResult =
    | { type: 'filter'; def: TableFilterDef<TData> }
    | { type: 'option'; def: TableFilterDef<TData>; opt: TableFilterOption }

  const filteredDefs = React.useMemo(
    () => filterDefs.filter(d => d.label.toLowerCase().includes(mainSearch.toLowerCase())),
    [filterDefs, mainSearch]
  )

  const searchResults = React.useMemo<SearchResult[] | null>(() => {
    if (!mainSearch) return null
    const q = mainSearch.toLowerCase()
    const results: SearchResult[] = []
    for (const def of filterDefs) {
      if (def.label.toLowerCase().includes(q)) {
        results.push({ type: 'filter', def })
      } else {
        for (const opt of def.options) {
          if (opt.label.toLowerCase().includes(q)) {
            results.push({ type: 'option', def, opt })
          }
        }
      }
    }
    return results
  }, [filterDefs, mainSearch])

  const activeList = searchResults ?? filteredDefs.map(def => ({ type: 'filter' as const, def }))

  const activeDef = (() => {
    if (searchResults) {
      const item = searchResults[highlightedMain]
      return item?.type === 'filter' ? item.def : null
    }
    return filteredDefs[highlightedMain] ?? null
  })()

  const filteredOptions = React.useMemo(
    () =>
      activeDef?.options.filter(o =>
        o.label.toLowerCase().includes(subSearch.toLowerCase())
      ) ?? [],
    [activeDef, subSearch]
  )

  const isSelected = (filterId: string, value: string) =>
    activeFilters.find(f => f.filterId === filterId)?.values.includes(value) ?? false

  const updateSubMenuTop = (index: number) => {
    const item = itemRefs.current[index]
    const popover = popoverRef.current
    if (!item || !popover) return
    const itemRect = item.getBoundingClientRect()
    const popoverRect = popover.getBoundingClientRect()
    setSubMenuTop(itemRect.top - popoverRect.top)
  }

  // Track mouse position
  React.useEffect(() => {
    if (!open) return
    const handler = (e: MouseEvent) => { mousePos.current = { x: e.clientX, y: e.clientY } }
    window.addEventListener('mousemove', handler)
    return () => {
      window.removeEventListener('mousemove', handler)
      if (aimTimer.current) clearTimeout(aimTimer.current)
    }
  }, [open])

  // True when mouse is within the triangle: anchorPos → submenu top-right → submenu bottom-right
  const isAimingAtSubmenu = () => {
    const subEl = subMenuRef.current
    if (!subEl) return false
    const r = subEl.getBoundingClientRect()
    const from = anchorPos.current
    const curr = mousePos.current
    if (curr.x >= from.x) return false  // moving right, not toward submenu
    // Vectors from anchor to the two right-edge corners of the submenu
    const dxTop = r.right - from.x;  const dyTop = r.top    - from.y
    const dxBot = r.right - from.x;  const dyBot = r.bottom - from.y
    // Vector from anchor to current position
    const dx = curr.x - from.x;      const dy = curr.y - from.y
    // Cross products: if both have same sign, curr is inside the cone
    const crossTop = dxTop * dy - dyTop * dx
    const crossBot = dxBot * dy - dyBot * dx
    return crossTop * crossBot <= 0
  }

  // Reset state when opening
  React.useEffect(() => {
    if (open) {
      setMainSearch('')
      setSubSearch('')
      setHighlightedMain(-1)
      setHighlightedSub(-1)
      setFocusedPanel('main')
      setTimeout(() => mainInputRef.current?.focus(), 0)
    }
  }, [open])

  // Keep highlightedMain in bounds when search changes (but don't promote -1)
  React.useEffect(() => {
    setHighlightedMain(prev => prev === -1 ? -1 : Math.min(prev, activeList.length - 1))
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeList.length])

  // Auto-select first row when active def changes
  React.useEffect(() => {
    setHighlightedSub(0)
    setSubSearch('')
  }, [activeDef?.id])

  // Update submenu position when highlighted item changes via keyboard
  React.useEffect(() => {
    if (highlightedMain >= 0) updateSubMenuTop(highlightedMain)
  }, [highlightedMain])

  // Deselect values hidden by the submenu search
  React.useEffect(() => {
    setHighlightedSub(0)
    if (!activeDef || !subSearch) return
    const visibleValues = new Set(filteredOptions.map(o => o.value))
    const selected = activeFilters.find(f => f.filterId === activeDef.id)?.values ?? []
    selected.filter(v => !visibleValues.has(v)).forEach(v => onToggleValue(activeDef.id, v))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [subSearch])

  // Scroll highlighted item into view
  React.useEffect(() => {
    if (focusedPanel === 'main' && highlightedMain >= 0) {
      mainListRef.current?.children[highlightedMain]?.scrollIntoView({ block: 'nearest' })
    }
  }, [highlightedMain, focusedPanel])

  React.useEffect(() => {
    if (focusedPanel === 'sub' && highlightedSub >= 0) {
      subListRef.current?.children[highlightedSub]?.scrollIntoView({ block: 'nearest' })
    }
  }, [highlightedSub, focusedPanel])

  const handleMainKeyDown = (e: React.KeyboardEvent) => {
    const n = activeList.length
    if (e.key === 'ArrowDown' || (e.key === 'Tab' && !e.shiftKey)) {
      e.preventDefault()
      setHighlightedMain(prev => prev === -1 ? 0 : (prev + 1) % n)
    } else if (e.key === 'ArrowUp' || (e.key === 'Tab' && e.shiftKey)) {
      e.preventDefault()
      setHighlightedMain(prev => prev <= 0 ? n - 1 : prev - 1)
    } else if (e.key === ' ' || e.key === 'Enter') {
      // Hovered sub-option takes priority — act on it from the main panel
      if (highlightedSub >= 0 && activeDef) {
        const opt = filteredOptions[highlightedSub]
        if (opt) {
          e.preventDefault()
          onToggleValue(activeDef.id, opt.value)
          if (e.key === 'Enter') onOpenChange(false)
        }
      } else if (e.key === 'Enter') {
        const idx = highlightedMain >= 0 ? highlightedMain : activeList.length === 1 ? 0 : -1
        const item = idx >= 0 ? activeList[idx] : null
        if (item) {
          e.preventDefault()
          if (item.type === 'option') {
            onToggleValue(item.def.id, item.opt.value)
            onOpenChange(false)
          } else if (item.type === 'filter') {
            if (filteredOptions.length === 1) {
              onToggleValue(item.def.id, filteredOptions[0].value)
              onOpenChange(false)
            } else {
              setFocusedPanel('sub')
              setTimeout(() => subInputRef.current?.focus(), 0)
            }
          }
        }
      }
    } else if (e.key === 'ArrowRight' && activeDef) {
      e.preventDefault()
      setFocusedPanel('sub')
      setTimeout(() => subInputRef.current?.focus(), 0)
    } else if (e.key === 'Escape') {
      onOpenChange(false)
    }
  }

  const handleSubKeyDown = (e: React.KeyboardEvent) => {
    const n = filteredOptions.length
    if (e.key === 'ArrowDown' || (e.key === 'Tab' && !e.shiftKey)) {
      e.preventDefault()
      setHighlightedSub(prev => prev === -1 ? 0 : (prev + 1) % n)
    } else if (e.key === 'ArrowUp' || (e.key === 'Tab' && e.shiftKey)) {
      e.preventDefault()
      setHighlightedSub(prev => prev <= 0 ? n - 1 : prev - 1)
    } else if (e.key === 'ArrowLeft' || e.key === 'Escape') {
      e.preventDefault()
      setFocusedPanel('main')
      setTimeout(() => mainInputRef.current?.focus(), 0)
    } else if (e.key === ' ' || e.key === 'Enter') {
      e.preventDefault()
      const opt = highlightedSub >= 0 ? filteredOptions[highlightedSub] : filteredOptions.length === 1 ? filteredOptions[0] : undefined
      if (opt && activeDef) {
        onToggleValue(activeDef.id, opt.value)
        if (e.key === 'Enter') onOpenChange(false)
      }
    }
  }

  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>{trigger}</PopoverTrigger>
      <PopoverContent
        ref={popoverRef}
        align="end"
        className="w-52 p-0 overflow-visible border border-white/10"
        onOpenAutoFocus={e => e.preventDefault()}
      >
        {/* Submenu — floats to the left, aligned to the highlighted item */}
        {activeDef && (
          <div
            ref={subMenuRef}
            className="absolute right-[calc(100%-8px)] w-52 bg-popover rounded-md border border-white/10 shadow-md flex flex-col overflow-hidden"
            style={{ top: subMenuTop }}
            onMouseEnter={() => { if (aimTimer.current) clearTimeout(aimTimer.current) }}
            onKeyDown={handleSubKeyDown}
          >
            <div className="border-b border-white/10 px-3 py-2">
              <input
                ref={subInputRef}
                placeholder="Filter..."
                value={subSearch}
                onChange={e => setSubSearch(e.target.value)}
                className="w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground"
                onFocus={() => setFocusedPanel('sub')}
              />
            </div>
            <div ref={subListRef} className="max-h-64 overflow-y-auto p-1">
              {filteredOptions.length === 0 && (
                <p className="py-4 text-center text-xs text-muted-foreground">No options.</p>
              )}
              {filteredOptions.map((opt, i) => {
                const selected = isSelected(activeDef.id, opt.value)
                return (
                  <button
                    key={opt.value}
                    className={cn(
                      'flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none',
                      i === highlightedSub && focusedPanel === 'sub'
                        ? 'bg-accent text-accent-foreground'
                        : 'hover:bg-accent hover:text-accent-foreground focus-visible:bg-accent focus-visible:text-accent-foreground'
                    )}
                    onMouseEnter={() => { setHighlightedSub(i); setFocusedPanel('sub') }}
                    onFocus={() => { setHighlightedSub(i); setFocusedPanel('sub') }}
                    onClick={() => { onToggleValue(activeDef.id, opt.value); onOpenChange(false) }}
                  >
                    <span className="flex h-3.5 w-3.5 shrink-0 items-center justify-center">
                      {selected && <CheckIcon className="h-3 w-3" />}
                    </span>
                    {opt.icon && <span className="shrink-0">{opt.icon}</span>}
                    <span className="truncate">{opt.label}</span>
                  </button>
                )
              })}
            </div>
          </div>
        )}

        {/* Main menu */}
        <div className="flex flex-col" onKeyDown={handleMainKeyDown}>
          <div className="border-b border-white/10 px-3 py-2 flex items-center gap-2">
            <input
              ref={mainInputRef}
              placeholder="Add Filter..."
              value={mainSearch}
              onChange={e => setMainSearch(e.target.value)}
              className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
              onFocus={() => setFocusedPanel('main')}
            />
            <span className="text-xs text-muted-foreground border border-white/10 rounded px-1">F</span>
          </div>
          <div ref={mainListRef} className="max-h-72 overflow-y-auto p-1">
            {activeList.length === 0 && (
              <p className="py-4 text-center text-xs text-muted-foreground">No filters found.</p>
            )}
            {activeList.map((item, i) => {
              const isHighlighted = i === highlightedMain
              const baseClass = cn(
                'flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none',
                isHighlighted
                  ? 'bg-accent text-accent-foreground'
                  : 'hover:bg-accent hover:text-accent-foreground focus-visible:bg-accent focus-visible:text-accent-foreground'
              )
              if (item.type === 'option') {
                const selected = isSelected(item.def.id, item.opt.value)
                return (
                  <button
                    key={`${item.def.id}:${item.opt.value}`}
                    ref={el => { itemRefs.current[i] = el }}
                    className={baseClass}
                    onMouseEnter={() => { setHighlightedMain(i); setFocusedPanel('main') }}
                    onFocus={() => { setHighlightedMain(i); setFocusedPanel('main') }}
                    onClick={() => onToggleValue(item.def.id, item.opt.value)}
                  >
                    {item.opt.icon && <span className="shrink-0 text-muted-foreground">{item.opt.icon}</span>}
                    <span className="flex-1 text-left truncate">
                      <span className="text-muted-foreground">{item.def.label}</span>
                      <span className="text-muted-foreground mx-1">›</span>
                      <span>{item.opt.label}</span>
                    </span>
                    {selected && <CheckIcon className="h-3 w-3 shrink-0" />}
                  </button>
                )
              }
              return (
                <button
                  key={item.def.id}
                  ref={el => { itemRefs.current[i] = el }}
                  className={baseClass}
                  onMouseEnter={() => {
                    const switchToItem = () => {
                      anchorPos.current = mousePos.current
                      setHighlightedMain(i)
                      setFocusedPanel('main')
                      updateSubMenuTop(i)
                    }
                    if (aimTimer.current) clearTimeout(aimTimer.current)
                    if (activeDef && isAimingAtSubmenu()) {
                      aimTimer.current = setTimeout(switchToItem, 200)
                    } else {
                      switchToItem()
                    }
                  }}
                  onFocus={() => { setHighlightedMain(i); setFocusedPanel('main') }}
                  onClick={() => {
                    anchorPos.current = mousePos.current
                    setHighlightedMain(i)
                    setFocusedPanel('sub')
                    setTimeout(() => subInputRef.current?.focus(), 0)
                  }}
                >
                  {item.def.icon && <span className="shrink-0 text-muted-foreground">{item.def.icon}</span>}
                  <span className="flex-1 text-left truncate">{item.def.label}</span>
                  <ChevronRightIcon className="h-3.5 w-3.5 text-muted-foreground" />
                </button>
              )
            })}
          </div>
        </div>
      </PopoverContent>
    </Popover>
  )
}

import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { type Row, flexRender } from '@tanstack/react-table'
import * as React from 'react'
import { TableCell, TableRow } from '@/components/ui/table'
import { cn } from '@/lib/utils'
import { rowStateClasses } from './ListRow'

export interface RowViewProps<TData> {
  row: Row<TData>
  displayIndex: number
  activeRowIndex: number | null
  activeRowSource: 'keyboard' | 'mouse'
  reorderable: boolean
  // True while this row is part of an active drag — kept in the list as an
  // opacity-0 placeholder so the layout (and group heights) stay correct.
  hidden?: boolean
  onRowClick: (index: number, shiftKey: boolean) => void
  onRowMouseEnter: (index: number) => void
  onContextMenu: (e: React.MouseEvent, index: number) => void
  prevSelected?: boolean
  nextSelected?: boolean
}

export function SortableRowCells<TData>({ row, isSelected, isActive, activeRowSource, prevSelected = false, nextSelected = false }: {
  row: Row<TData>
  isSelected: boolean
  isActive: boolean
  activeRowSource: 'keyboard' | 'mouse'
  prevSelected?: boolean
  nextSelected?: boolean
}) {
  const cells = row.getVisibleCells()
  const hasBackground = isSelected || isActive
  const isRing = isActive && activeRowSource === 'keyboard'
  const tb = 'inset 0 1px 0 0 var(--selected-border), inset 0 -1px 0 0 var(--selected-border)'

  return (
    <>
      {cells.map((cell, ci) => {
        const isFirst = ci === 0
        const isLast = ci === cells.length - 1
        let boxShadow: string | undefined
        if (isRing) {
          if (isFirst && isLast) boxShadow = `inset 1px 0 0 0 var(--selected-border), inset -1px 0 0 0 var(--selected-border), ${tb}`
          else if (isFirst)     boxShadow = `inset 1px 0 0 0 var(--selected-border), ${tb}`
          else if (isLast)      boxShadow = `inset -1px 0 0 0 var(--selected-border), ${tb}`
          else                  boxShadow = tb
        }
        return (
          <TableCell
            key={cell.id}
            className={cn(
              'py-1.5 text-sm',
              cell.column.id === '_select' && 'w-6 !pl-2 !pr-0',
              isFirst && hasBackground && !(isSelected && prevSelected) && 'rounded-tl-md',
              isFirst && hasBackground && !(isSelected && nextSelected) && 'rounded-bl-md',
              isLast  && hasBackground && !(isSelected && prevSelected) && 'rounded-tr-md',
              isLast  && hasBackground && !(isSelected && nextSelected) && 'rounded-br-md',
            )}
            style={boxShadow ? { boxShadow } : undefined}
          >
            {cell.column.id === '_select' ? (
              <span className={cn('flex items-center', !isSelected && !isActive && 'opacity-0')}>
                {flexRender(cell.column.columnDef.cell, cell.getContext())}
              </span>
            ) : (
              flexRender(cell.column.columnDef.cell, cell.getContext())
            )}
          </TableCell>
        )
      })}
    </>
  )
}

export function SortableRow<TData>({
  row,
  displayIndex,
  activeRowIndex,
  activeRowSource,
  reorderable,
  hidden,
  onRowClick,
  onRowMouseEnter,
  onContextMenu,
  prevSelected,
  nextSelected,
}: RowViewProps<TData>) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: row.id,
    disabled: !reorderable,
    // Animate while actively sorting (rows reposition smoothly as you drag
    // over them), but not on drop — live reflow already placed the row, so a
    // settle animation would replay that move and cause a flip.
    animateLayoutChanges: ({ isSorting }) => isSorting === true,
  })

  const isSelected = row.getIsSelected()
  const isActive = activeRowIndex === displayIndex

  return (
    <TableRow
      ref={setNodeRef}
      {...(reorderable ? attributes : {})}
      {...(reorderable ? listeners : {})}
      tabIndex={-1}
      style={{
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: hidden || isDragging ? 0 : undefined,
      }}
      data-display-index={displayIndex}
      data-state={isSelected ? 'selected' : undefined}
      className={cn(
        'h-6 select-none outline-none',
        reorderable ? 'cursor-grab active:cursor-grabbing' : 'cursor-pointer',
        rowStateClasses(isSelected, isActive),
      )}
      onClick={(e) => onRowClick(displayIndex, e.shiftKey)}
      onMouseEnter={() => onRowMouseEnter(displayIndex)}
      onContextMenu={(e) => onContextMenu(e, displayIndex)}
    >
      <SortableRowCells row={row} isSelected={isSelected} isActive={isActive} activeRowSource={activeRowSource} prevSelected={prevSelected} nextSelected={nextSelected} />
    </TableRow>
  )
}

import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { type Row, flexRender } from '@tanstack/react-table'
import { cn } from '@/lib/utils'
import type { RowViewProps } from './SortableRow'

export const listRowClassName =
  'flex items-center gap-2 px-2 py-1.5 select-none outline-none text-sm'

export function rowStateClasses(isSelected: boolean, isActive: boolean) {
  return cn(
    isSelected && 'bg-selected/10',
    isActive && isSelected && 'bg-selected/15',
    isActive && !isSelected && 'bg-muted/50',
  )
}

export function ListRowCells<TData>({ row, isSelected, activeRowIndex, displayIndex }: {
  row: Row<TData>
  isSelected: boolean
  activeRowIndex: number | null
  displayIndex: number
}) {
  const cells = row.getVisibleCells()
  const growIdx = cells.findIndex(c => (c.column.columnDef.meta as Record<string, unknown> | undefined)?.grow === true)
  const leadingCells = growIdx === -1 ? cells : cells.slice(0, growIdx + 1)
  const trailingCells = growIdx === -1 ? [] : cells.slice(growIdx + 1)

  return (
    <>
      {leadingCells.map((cell) => {
        const meta = cell.column.columnDef.meta as Record<string, unknown> | undefined
        const grow = meta?.grow === true

        if (cell.column.id === '_select') {
          return (
            <span
              key={cell.id}
              className={cn(
                'flex items-center shrink-0',
                !isSelected && activeRowIndex !== displayIndex && 'opacity-0',
              )}
            >
              {flexRender(cell.column.columnDef.cell, cell.getContext())}
            </span>
          )
        }

        const size = cell.column.columnDef.size
        return (
          <div
            key={cell.id}
            className={cn(grow ? 'flex-1 min-w-0 truncate' : 'shrink-0')}
            style={!grow && size ? { width: size } : undefined}
          >
            {flexRender(cell.column.columnDef.cell, cell.getContext())}
          </div>
        )
      })}
      {trailingCells.length > 0 && (
        <div className="ml-auto flex items-center gap-2 shrink-0">
          {trailingCells.map((cell) => (
            <div key={cell.id}>
              {flexRender(cell.column.columnDef.cell, cell.getContext())}
            </div>
          ))}
        </div>
      )}
    </>
  )
}

export function ListRow<TData>({
  row,
  displayIndex,
  activeRowIndex,
  activeRowSource,
  reorderable,
  hidden,
  onRowClick,
  onRowMouseEnter,
  onContextMenu,
  prevSelected,
  nextSelected,
}: RowViewProps<TData>) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: row.id,
    disabled: !reorderable,
    // Animate while actively sorting (rows reposition smoothly as you drag
    // over them), but not on drop — live reflow already placed the row, so a
    // settle animation would replay that move and cause a flip.
    animateLayoutChanges: ({ isSorting }) => isSorting === true,
  })

  const isSelected = row.getIsSelected()
  const isActive = activeRowIndex === displayIndex
  const hasBackground = isSelected || isActive
  const isRing = isActive && activeRowSource === 'keyboard'

  return (
    <div
      ref={setNodeRef}
      {...(reorderable ? attributes : {})}
      {...(reorderable ? listeners : {})}
      tabIndex={-1}
      style={{
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: hidden || isDragging ? 0 : undefined,
        boxShadow: isRing ? 'inset 0 0 0 1px var(--selected-border)' : undefined,
      }}
      data-display-index={displayIndex}
      data-state={isSelected ? 'selected' : undefined}
      className={cn(
        listRowClassName,
        reorderable ? 'cursor-grab active:cursor-grabbing' : 'cursor-pointer',
        rowStateClasses(isSelected, isActive),
        hasBackground && !(isSelected && prevSelected) && 'rounded-t-md',
        hasBackground && !(isSelected && nextSelected) && 'rounded-b-md',
      )}
      onClick={(e) => onRowClick(displayIndex, e.shiftKey)}
      onMouseEnter={() => onRowMouseEnter(displayIndex)}
      onContextMenu={(e) => onContextMenu(e, displayIndex)}
    >
      <ListRowCells row={row} isSelected={isSelected} activeRowIndex={activeRowIndex} displayIndex={displayIndex} />
    </div>
  )
}

import { XIcon } from 'lucide-react'
import * as React from 'react'
import { Button } from '@/components/ui/button'
import type { TableActiveFilter, TableFilterDef } from './types'

interface FilterBarProps<TData> {
  filterDefs: TableFilterDef<TData>[]
  activeFilters: TableActiveFilter[]
  onRemoveFilter: (filterId: string) => void
  onClearAll?: () => void
}

export function FilterBar<TData>({ filterDefs, activeFilters, onRemoveFilter, onClearAll }: FilterBarProps<TData>) {
  if (activeFilters.length === 0) return null

  return (
    <div className="flex items-center gap-2 flex-wrap">
      <div className="flex items-center gap-1.5 flex-wrap flex-1">
        {activeFilters.map(af => {
          const def = filterDefs.find(d => d.id === af.filterId)
          if (!def) return null
          const valueLabels = af.values.map(v => {
            const opt = def.options.find(o => o.value === v)
            return (
              <span key={v} className="inline-flex items-center gap-1">
                {opt?.icon && <span className="shrink-0">{opt.icon}</span>}
                <span>{opt?.label ?? v}</span>
              </span>
            )
          })

          return (
            <span
              key={af.filterId}
              className="inline-flex items-center gap-1.5 rounded-md border border-border bg-muted dark:bg-muted/50 px-2 py-1 text-xs"
            >
              {def.icon && <span className="text-muted-foreground shrink-0">{def.icon}</span>}
              <span className="text-muted-foreground">{def.label}</span>
              <span className="text-muted-foreground">is</span>
              <span className="flex items-center gap-1 flex-wrap">
                {valueLabels.reduce<React.ReactNode[]>((acc, el, i) => {
                  if (i > 0) acc.push(<span key={`sep-${i}`} className="text-muted-foreground">,</span>)
                  acc.push(el)
                  return acc
                }, [])}
              </span>
              <button
                onClick={() => onRemoveFilter(af.filterId)}
                className="ml-0.5 rounded-sm text-muted-foreground hover:text-foreground outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
                aria-label={`Remove ${def.label} filter`}
              >
                <XIcon className="h-3 w-3" />
              </button>
            </span>
          )
        })}
      </div>
      {onClearAll && (
        <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onClearAll}>
          Clear
        </Button>
      )}
    </div>
  )
}

